  constructor(ttl = 300000) {
    this.cache = {};
    this.ttl = ttl;
  }

  get(city) {
    const entry = this.cache[city];
    if (entry && entry.expires > Date.now()) {
      return entry.data;
    }
    return null;
  }

  set(city, data) {
    this.cache[city] = {
      data,
      expires: Date.now() + this.ttl
